import { parseSpectrum } from './speclib.js';

// Library text is UTF-8 when it is valid UTF-8, and Windows-1252 (a superset of Latin-1) otherwise.
export function decodeLibraryText(bytes) {
  try {
    return new TextDecoder('utf-8', { fatal: true }).decode(bytes);
  } catch {
    return new TextDecoder('windows-1252').decode(bytes);
  }
}

// Import dropped spectrum files.
export async function importSpectra(library, files) {
  for (const file of files) {
    const text = decodeLibraryText(new Uint8Array(await file.arrayBuffer()));
    library.import(file.name, [parseSpectrum(text)]);
  }
}

