import { test } from 'node:test';
import assert from 'node:assert/strict';
import { decodeLibraryText, importSpectra } from '../src/library-import.js';

test('UTF-8 text is decoded as UTF-8', () => {
  assert.equal(decodeLibraryText(new TextEncoder().encode('Na2CO3·10H2O')), 'Na2CO3·10H2O');
});

test('Latin-1 text keeps its middle dot', () => {
  const bytes = Uint8Array.from([0x4e, 0x61, 0xb7, 0x31, 0x30]);
  assert.equal(decodeLibraryText(bytes), 'Na·10');
});

test('a dropped Latin-1 file imports with its name intact', async () => {
  const bytes = Uint8Array.from([...new TextEncoder().encode('natron '), 0xb7, ...new TextEncoder().encode('\n0.4 12\n')]);
  const file = { name: 'natron.txt', arrayBuffer: async () => bytes.buffer };
  const imported = [];
  await importSpectra({ import: (name, spectra) => imported.push(...spectra) }, [file]);
  assert.equal(imported[0].name, 'natron ·');
});
